# The Complete Guide to Authentication & Authorization

Security is non-negotiable. This guide covers everything you need to implement robust authentication and authorization in your full-stack applications.

## Authentication vs Authorization

**Authentication (AuthN)**: Who are you?
- Verifying identity
- Login process
- Credentials validation

**Authorization (AuthZ)**: What can you do?
- Access control
- Permissions
- Role-based access

```
User → [Authentication] → Identity Confirmed
     → [Authorization] → Access Granted/Denied
```

## Session-Based Authentication

### How It Works

```
1. User sends credentials
2. Server validates credentials
3. Server creates session, stores in database
4. Server sends session ID in cookie
5. Browser sends cookie with every request
6. Server validates session ID
```

### Implementation

```javascript
// Express.js with express-session
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const redis = require('redis');

const redisClient = redis.createClient();

app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true,       // HTTPS only
    httpOnly: true,     // Not accessible via JavaScript
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
    sameSite: 'strict'  // CSRF protection
  }
}));

// Login route
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findByEmail(email);
  if (!user || !await bcrypt.compare(password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Create session
  req.session.userId = user.id;
  req.session.role = user.role;

  res.json({ user: { id: user.id, email: user.email } });
});

// Protected route
app.get('/profile', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

// Middleware
function requireAuth(req, res, next) {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  next();
}

// Logout
app.post('/logout', (req, res) => {
  req.session.destroy((err) => {
    res.clearCookie('connect.sid');
    res.json({ message: 'Logged out' });
  });
});
```

### Pros & Cons

**Pros:**
- Simple to implement
- Easy to invalidate (delete session)
- Server controls session state

**Cons:**
- Requires server-side storage
- Hard to scale horizontally
- Not ideal for mobile apps/APIs

## JWT (JSON Web Token) Authentication

### How It Works

```
1. User sends credentials
2. Server validates credentials
3. Server creates signed JWT
4. Server sends JWT to client
5. Client stores JWT (localStorage/cookie)
6. Client sends JWT in Authorization header
7. Server validates JWT signature
```

### JWT Structure

```
header.payload.signature

// Header
{
  "alg": "HS256",
  "typ": "JWT"
}

// Payload
{
  "sub": "user123",
  "email": "user@example.com",
  "role": "admin",
  "iat": 1609459200,
  "exp": 1609545600
}

// Signature
HMACSHA256(
  base64UrlEncode(header) + "." + base64UrlEncode(payload),
  secret
)
```

### Implementation

```javascript
const jwt = require('jsonwebtoken');

// Generate tokens
function generateTokens(user) {
  const accessToken = jwt.sign(
    { sub: user.id, email: user.email, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '15m' }
  );

  const refreshToken = jwt.sign(
    { sub: user.id },
    process.env.REFRESH_SECRET,
    { expiresIn: '7d' }
  );

  return { accessToken, refreshToken };
}

// Login
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findByEmail(email);
  if (!user || !await bcrypt.compare(password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const { accessToken, refreshToken } = generateTokens(user);

  // Store refresh token in HTTP-only cookie
  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000
  });

  res.json({ accessToken });
});

// Middleware to verify JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    return res.status(403).json({ error: 'Invalid token' });
  }
}

// Refresh token endpoint
app.post('/refresh', (req, res) => {
  const refreshToken = req.cookies.refreshToken;

  if (!refreshToken) {
    return res.status(401).json({ error: 'No refresh token' });
  }

  try {
    const decoded = jwt.verify(refreshToken, process.env.REFRESH_SECRET);
    const user = await User.findById(decoded.sub);

    const { accessToken, refreshToken: newRefreshToken } = generateTokens(user);

    res.cookie('refreshToken', newRefreshToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000
    });

    res.json({ accessToken });
  } catch (error) {
    res.status(403).json({ error: 'Invalid refresh token' });
  }
});

// Protected route
app.get('/profile', authenticateToken, (req, res) => {
  res.json({ user: req.user });
});
```

### Frontend Implementation

```javascript
// API client with automatic token refresh
class AuthAPI {
  constructor() {
    this.accessToken = null;
  }

  async login(email, password) {
    const response = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include', // For cookies
      body: JSON.stringify({ email, password })
    });

    const data = await response.json();
    this.accessToken = data.accessToken;
    return data;
  }

  async fetchWithAuth(url, options = {}) {
    const response = await fetch(url, {
      ...options,
      headers: {
        ...options.headers,
        'Authorization': `Bearer ${this.accessToken}`
      },
      credentials: 'include'
    });

    // Token expired, try refresh
    if (response.status === 401) {
      await this.refreshToken();
      return this.fetchWithAuth(url, options);
    }

    return response;
  }

  async refreshToken() {
    const response = await fetch('/api/refresh', {
      method: 'POST',
      credentials: 'include'
    });

    if (!response.ok) {
      throw new Error('Session expired');
    }

    const data = await response.json();
    this.accessToken = data.accessToken;
  }
}
```

## OAuth 2.0

### Authorization Code Flow

```
1. User clicks "Login with Google"
2. Redirect to Google authorization page
3. User grants permission
4. Google redirects back with authorization code
5. Server exchanges code for access token
6. Server gets user info from Google
7. Server creates session/JWT for user
```

### Implementation with Passport.js

```javascript
const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;

passport.use(new GoogleStrategy({
    clientID: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    callbackURL: '/auth/google/callback'
  },
  async (accessToken, refreshToken, profile, done) => {
    try {
      // Find or create user
      let user = await User.findByGoogleId(profile.id);

      if (!user) {
        user = await User.create({
          googleId: profile.id,
          email: profile.emails[0].value,
          name: profile.displayName
        });
      }

      return done(null, user);
    } catch (error) {
      return done(error, null);
    }
  }
));

// Routes
app.get('/auth/google',
  passport.authenticate('google', { scope: ['profile', 'email'] })
);

app.get('/auth/google/callback',
  passport.authenticate('google', { failureRedirect: '/login' }),
  (req, res) => {
    const { accessToken, refreshToken } = generateTokens(req.user);
    res.redirect(`/auth-callback?token=${accessToken}`);
  }
);
```

## Role-Based Access Control (RBAC)

### Database Schema

```sql
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL
);

CREATE TABLE roles (
    id SERIAL PRIMARY KEY,
    name VARCHAR(50) UNIQUE NOT NULL
);

CREATE TABLE permissions (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) UNIQUE NOT NULL
);

CREATE TABLE user_roles (
    user_id INT REFERENCES users(id),
    role_id INT REFERENCES roles(id),
    PRIMARY KEY (user_id, role_id)
);

CREATE TABLE role_permissions (
    role_id INT REFERENCES roles(id),
    permission_id INT REFERENCES permissions(id),
    PRIMARY KEY (role_id, permission_id)
);

-- Sample data
INSERT INTO roles (name) VALUES ('admin'), ('editor'), ('viewer');
INSERT INTO permissions (name) VALUES 
    ('users:read'), ('users:write'), ('users:delete'),
    ('posts:read'), ('posts:write'), ('posts:delete');
```

### Authorization Middleware

```javascript
// Check role
function requireRole(...roles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// Check permission
function requirePermission(permission) {
  return async (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    const userPermissions = await getUserPermissions(req.user.id);

    if (!userPermissions.includes(permission)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// Usage
app.get('/admin/users', 
  authenticateToken, 
  requireRole('admin'),
  (req, res) => {
    // Admin only
  }
);

app.post('/posts',
  authenticateToken,
  requirePermission('posts:write'),
  (req, res) => {
    // Users with posts:write permission
  }
);
```

## Password Security

### Hashing Passwords

```javascript
const bcrypt = require('bcrypt');

// Hash password (on registration)
const saltRounds = 12;
const passwordHash = await bcrypt.hash(password, saltRounds);

// Verify password (on login)
const isValid = await bcrypt.compare(password, user.passwordHash);
```

### Password Requirements

```javascript
function validatePassword(password) {
  const errors = [];

  if (password.length < 8) {
    errors.push('Password must be at least 8 characters');
  }
  if (!/[A-Z]/.test(password)) {
    errors.push('Password must contain uppercase letter');
  }
  if (!/[a-z]/.test(password)) {
    errors.push('Password must contain lowercase letter');
  }
  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain a number');
  }
  if (!/[^A-Za-z0-9]/.test(password)) {
    errors.push('Password must contain a special character');
  }

  return errors;
}
```

## Security Best Practices

### HTTPS Always

```javascript
// Force HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}
```

### Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts
  message: 'Too many login attempts, try again later'
});

app.post('/login', loginLimiter, loginHandler);
```

### CORS Configuration

```javascript
const cors = require('cors');

app.use(cors({
  origin: ['https://myapp.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

### Security Headers

```javascript
const helmet = require('helmet');
app.use(helmet());

// Manual headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});
```

## Summary Checklist

### Authentication
1. ✅ Use HTTPS everywhere
2. ✅ Hash passwords with bcrypt (cost 12+)
3. ✅ Implement rate limiting on login
4. ✅ Use short-lived access tokens
5. ✅ Store refresh tokens securely
6. ✅ Implement proper logout

### Authorization
1. ✅ Check permissions on every request
2. ✅ Use principle of least privilege
3. ✅ Validate user owns resources
4. ✅ Log authorization failures

### Sessions/Tokens
1. ✅ Set secure cookie flags
2. ✅ Rotate session IDs on login
3. ✅ Implement token refresh
4. ✅ Handle token expiration gracefully

## Conclusion

Security is a continuous process. Start with solid fundamentals, then layer additional protections as needed.

**Key Takeaways:**
1. Choose auth strategy based on use case
2. Always hash passwords
3. Use HTTPS and secure cookies
4. Implement proper RBAC
5. Rate limit sensitive endpoints
6. Log security events

Stay secure!
